const header=document.querySelector('.site-header');const menuButton=document.querySelector('.menu-toggle');const nav=document.querySelector('.site-nav');const backTop=document.querySelector('.back-top');
const closeMenu=()=>{nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false')};
menuButton.addEventListener('click',()=>{const open=nav.classList.toggle('open');menuButton.setAttribute('aria-expanded',String(open))});
document.querySelectorAll('.dropdown-toggle').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();const parent=button.parentElement;document.querySelectorAll('.dropdown.open').forEach(item=>{if(item!==parent){item.classList.remove('open');item.querySelector('button').setAttribute('aria-expanded','false')}});const open=parent.classList.toggle('open');button.setAttribute('aria-expanded',String(open))}));
document.addEventListener('click',()=>document.querySelectorAll('.dropdown.open').forEach(item=>{item.classList.remove('open');item.querySelector('button').setAttribute('aria-expanded','false')}));
document.querySelectorAll('.site-nav a').forEach(link=>link.addEventListener('click',closeMenu));
window.addEventListener('scroll',()=>{header.classList.toggle('scrolled',scrollY>20);backTop.classList.toggle('show',scrollY>650)},{passive:true});
const tabs=[...document.querySelectorAll('.tab')];tabs.forEach(tab=>tab.addEventListener('click',()=>{tabs.forEach(t=>{t.classList.remove('active');t.setAttribute('aria-selected','false')});tab.classList.add('active');tab.setAttribute('aria-selected','true');document.querySelectorAll('.tab-panel').forEach(panel=>panel.hidden=panel.id!==tab.dataset.tab)}));
const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');revealObserver.unobserve(entry.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>revealObserver.observe(el));
let countersStarted=false;const numberFormatter=new Intl.NumberFormat('en-US');const animateCounters=()=>{if(countersStarted)return;countersStarted=true;document.querySelectorAll('.counter').forEach(counter=>{const target=Number(counter.dataset.target);const suffix=counter.dataset.suffix||'';const start=performance.now();const duration=1700;const frame=now=>{const progress=Math.min((now-start)/duration,1);const eased=1-Math.pow(1-progress,3);counter.textContent=numberFormatter.format(Math.round(target*eased))+suffix;if(progress<1)requestAnimationFrame(frame)};requestAnimationFrame(frame)})};
const statsObserver=new IntersectionObserver(entries=>{if(entries[0].isIntersecting){animateCounters();statsObserver.disconnect()}},{threshold:.35});statsObserver.observe(document.querySelector('.stats'));
const quotes=[{quote:'“Fabklean streamlined everything in just one month and brought our multi-store business back under control.”',detail:'We used to lose money through missing garments, expenses and compensation every month. Today, every moving part is visible.',name:'Deepak G.',role:'Owner, Pearlwash · Hyderabad',initials:'DG'},{quote:'“We opened our second outlet without adding administrative overhead. The visibility is remarkable.”',detail:'Orders, staff, collections and deliveries now move through one system. Our customers immediately noticed the difference.',name:'Anita Rao',role:'Founder, Fresh Fold · Bengaluru',initials:'AR'},{quote:'“Our drivers complete more pickups, and customers always know where their order is.”',detail:'Automated notifications and smarter routes have removed dozens of daily calls while improving on-time delivery.',name:'Rahul Mehta',role:'Director, Laundry Lab · Mumbai',initials:'RM'}];let quoteIndex=0;const renderQuote=()=>{const q=quotes[quoteIndex];document.querySelector('.quote blockquote').textContent=q.quote;document.querySelector('.quote>p').textContent=q.detail;document.querySelector('.person-avatar').textContent=q.initials;document.querySelector('.person b').textContent=q.name;document.querySelector('.person span').textContent=q.role;document.querySelector('.quote-controls span').textContent=`0${quoteIndex+1} / 03`};const quoteButtons=document.querySelectorAll('.quote-controls button');quoteButtons[0].addEventListener('click',()=>{quoteIndex=(quoteIndex+quotes.length-1)%quotes.length;renderQuote()});quoteButtons[1].addEventListener('click',()=>{quoteIndex=(quoteIndex+1)%quotes.length;renderQuote()});
document.querySelector('#newsletter').addEventListener('submit',event=>{event.preventDefault();const message=document.querySelector('.form-message');message.textContent='Thanks — you’re on the list!';event.target.reset()});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){closeMenu();document.querySelectorAll('.dropdown.open').forEach(item=>item.classList.remove('open'))}});
document.querySelectorAll('a[href="https://app.fabklean.com/laundry/login"]').forEach(a=>a.href='login.html');
document.querySelectorAll('a[href="https://app.fabklean.com/laundry/signup"]').forEach(a=>a.href='signup.html');
